// static
bool UnionTraits<::glic::mojom::OverlayState::DataView, ::glic::mojom::OverlayStatePtr>::Read(
    ::glic::mojom::OverlayState::DataView input,
    ::glic::mojom::OverlayStatePtr* output) {
  using UnionType = ::glic::mojom::OverlayState;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kLoading: {
      ::glic::mojom::LoadingStyle result_loading;
      if (!input.ReadLoading(&result_loading))
        return false;

      *output = UnionType::NewLoading(result_loading);
      break;
    }
    case Tag::kError: {
      ::glic::mojom::ErrorPanelType result_error;
      if (!input.ReadError(&result_error))
        return false;

      *output = UnionType::NewError(result_error);
      break;
    }
    default:

      return false;
  }
  return true;
}

